import React from 'react';
import {Link} from 'react-router-dom';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {projects} from '../data/site';
export default function Projects(){return <><Seo title="Projets" path="/projets" description="Aracore, aracnet et CRAPH.fr : les projets présentés sur Beyond31."/><section className="page-hero elegant-page"><p className="eyebrow"><span/>Projets</p><h1>Pas des concepts.<br/><em>Des choses qui existent.</em></h1><p>Chaque projet répond à un besoin différent. Leur point commun : ils ont obligé à apprendre quelque chose de concret.</p></section><section className="projects-index">{projects.map((p,i)=><Link to={`/projets/${p.slug}`} className="project-index-row" key={p.slug}><div className="project-index-n">{String(i+1).padStart(2,'0')}</div><div><p>{p.kind} · {p.year}</p><h2>{p.name}</h2><span>{p.headline}</span></div><div className="project-index-tools">{p.roles.slice(0,3).map(r=><span key={r}>{r}</span>)}</div><div className="project-index-arrow"><Icon name="arrow"/></div></Link>)}</section></>}
